function explanationContent(plan,overview=false){const info=trainingExplanation(plan);return `<div class="training-explanation">${overview?'<p class="small muted">Your current training picture, calculated from saved workouts and today’s plan.</p>':''}${info.entries.map(entry=>`<section class="explanation-line"><h3>${esc(entry.title)}</h3><ul>${entry.points.map(point=>`<li>${esc(point)}</li>`).join('')}</ul></section>`).join('')}<details class="explanation-method"><summary>How the engine decides</summary><p class="small">Each movement progresses independently. Clean, qualifying sessions build a progression cycle; reduced or incomplete work does not earn advancement. A completed cycle may change volume, density or the next training step depending on the movement’s policy. The current plan and recorded work—not an AI prediction—drive this explanation.</p></details></div>`;}
function programDecision(p){return `<details class="card" id="program-decision"><summary>Why this workout?</summary>${explanationContent(p)}</details>`;}

